import json, os, re

BASE = "C:/Users/Administrator/.dsh/cache/memory-audit"
ROOT = "D:/repository"
d = json.load(open(BASE + "/select.json", encoding="utf-8"))

dirs = [x for x in os.listdir(ROOT) if os.path.isdir(os.path.join(ROOT, x))]
SKIP = {'node_modules', '.git', 'dist', 'build', '.idea', 'coverage', 'vendor', '.vscode'}

def find_project_dir(project):
    if not project:
        return None
    cands = []
    for name in dirs:
        if project == name or project in name or name in project:
            cands.append(name)
    if not cands:
        return None
    cands.sort(key=len)
    return os.path.join(ROOT, cands[0])

_idx_cache = {}
def index_dir(path):
    if path in _idx_cache:
        return _idx_cache[path]
    idx = {}
    cnt = 0
    for dp, dns, fns in os.walk(path):
        dns[:] = [x for x in dns if x not in SKIP]
        for f in fns:
            idx.setdefault(f, []).append(os.path.join(dp, f))
            cnt += 1
        if cnt > 60000:
            break
    _idx_cache[path] = idx
    return idx

rows = []
for i, c in enumerate(d['candidates'], 1):
    content = c['content']
    uri = c['uri']
    sha = c['body_sha256_16']
    cat = 'preference' if '/preferences/' in uri else 'entity'
    m = re.search(r'(?:所属项目|项目)[：:]\s*([^\s；;，,。、]+)', content)
    project = m.group(1) if m else ''
    pdir = find_project_dir(project)
    files = set(re.findall(r'[\w\-]+\.(?:vue|js|ts|jsx|tsx|py|json|scss|css|java|mjs)\b', content))
    files = {f for f in files if len(f) > 4 and f not in ('index.vue', 'index.js')}
    found = []
    if pdir:
        idx = index_dir(pdir)
        for f in files:
            if f in idx:
                found.append(f)
    # key symbols from backticks (identifier-like)
    syms = set(re.findall(r'`([A-Za-z_][\w]{3,})`', content))
    stop = {'true','false','null','undefined','none','disabled','center','flex-start','extracted','source'}
    syms = {s for s in syms if s.lower() not in stop}
    rows.append({
        'i': i, 'sha': sha, 'cat': cat, 'project': project,
        'pdir': os.path.basename(pdir) if pdir else None,
        'files_total': len(files), 'files_found': len(found),
        'found': sorted(found)[:6],
        'files_sample': sorted(files)[:6],
        'syms': sorted(syms)[:8],
        'head': content[:220].replace('\n', ' '),
    })

with open(BASE + '/evidence.json', 'w', encoding='utf-8') as f:
    json.dump(rows, f, ensure_ascii=False, indent=1)

# compact text report
with open(BASE + '/evidence.txt', 'w', encoding='utf-8') as f:
    for r in rows:
        f.write("{i}|{sha}|{cat}|proj={project}|dir={pdir}|files={fo}/{ft}|syms={syms}\n  head: {head}\n  found: {found}\n".format(
            i=r['i'], sha=r['sha'], cat=r['cat'], project=r['project'], pdir=r['pdir'],
            fo=r['files_found'], ft=r['files_total'], syms=','.join(r['syms']),
            head=r['head'], found=','.join(r['found'])))
print('ok rows=', len(rows))

import json, os, re

BASE = "C:/Users/Administrator/.dsh/cache/memory-audit"
ROOT = "D:/repository"
d = json.load(open(BASE + "/select.json", encoding="utf-8"))

STOP = set('''extracted source cursor project codebase none true false undefined null disabled
center flex start own detail scope value label type list data info index components views
src admin web mobile h5 moduleName businessName buttons computed methods template
the and for with this that from into only when will have been were they them then
version config default return import export function const let var class object string'''.split())

def extract_syms(content):
    s = set(re.findall(r'`([A-Za-z_$][\w$.\-]{5,})`', content))
    s |= set(re.findall(r'\b([a-z]+[A-Z]\w{5,})\b', content))
    out = []
    for x in s:
        x = x.strip('`')
        if x.lower() in STOP or x in STOP:
            continue
        if '.' in x and len(x) > 40:
            continue
        out.append(x)
    # prefer distinctive: longer first
    out.sort(key=lambda z: (-len(z), z))
    return out[:6]

items = [{'i': i, 'sha': c['body_sha256_16'], 'syms': extract_syms(c['content'])}
         for i, c in enumerate(d['candidates'], 1)]

allsyms = set()
for it in items:
    allsyms.update(it['syms'])
allsyms = {s for s in allsyms if len(s) >= 5}

hits = {s: [] for s in allsyms}
SKIP = {'node_modules', '.git', 'dist', 'build', '.idea', 'coverage', 'vendor',
        '.vscode', '.cache', '__pycache__', 'target', 'out'}
EXT = {'.js', '.ts', '.vue', '.jsx', '.tsx', '.mjs'}
fcnt = 0
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [x for x in dns if x not in SKIP]
    for fn in fns:
        if os.path.splitext(fn)[1].lower() not in EXT:
            continue
        p = os.path.join(dp, fn)
        try:
            if os.path.getsize(p) > 3_000_000:
                continue
            with open(p, encoding='utf-8', errors='ignore') as f:
                text = f.read()
        except Exception:
            continue
        fcnt += 1
        for s in allsyms:
            if s in text and len(hits[s]) < 3:
                hits[s].append(os.path.relpath(p, ROOT))

with open(BASE + '/symcheck.txt', 'w', encoding='utf-8') as f:
    f.write('files_scanned={}\n'.format(fcnt))
    for it in items:
        parts = []
        for s in it['syms']:
            n = len(hits[s])
            sample = hits[s][0] if hits[s] else '-'
            parts.append('{}={}({})'.format(s, n, sample))
        f.write('{}|{}|{}\n'.format(it['i'], it['sha'], ' | '.join(parts)))
print('ok files=', fcnt, 'syms=', len(allsyms))

